contract InvMutTest {
    C c;

    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 h, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 1 ether, "amount must be 1 ether");
        require(address(this).balance >= amount, "not enough balance");

        c.lockInGuess{value: amount}(h); if (__ESBMC_reverted()) return;

        bool firstSettleReverted;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstSettleReverted = true;
        } else {
            firstSettleReverted = false;
        }

        bool secondSettleReverted;
        c.settle(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondSettleReverted = true;
        } else {
            secondSettleReverted = false;
        }

        assert(firstSettleReverted || secondSettleReverted);
    }

    receive() external payable {}
}

