// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 h, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 1 ether;
        vm.assume(address(this).balance >= amount);
        try c.lockInGuess{value: amount}(h) {} catch { return; }
        bool firstSettleReverted;
        try c.settle() {
            firstSettleReverted = false;
        } catch {
            firstSettleReverted = true;
        }
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }
        assertTrue(firstSettleReverted || secondSettleReverted);
    }

    function testFuzz_run(bytes32 h, uint256 amount) public {
        _run(h, amount);
    }

    receive() external payable {}
}
